          setTimeout(() => hold.release(), 500);
        }
        if (type === 'conversation_list') hold.release();
        if (type === 'stream_end') resolve();
      });
    });

    const end = types.indexOf('stream_end');
    expect({listed: types.includes('conversation_list'), beforeEnd: types.indexOf('conversation_list') < end}).toEqual({
      listed: true,
      beforeEnd: true,
    });
  });

  it('resumes a conversation picked from the list through the existing ?sessionId reconnect, replay included', async () => {
    const base = await start(storeWithThree(), {history: {enabled: true}});
    const {frames} = await exchange(base, [{type: 'list_conversations'}]);
    const picked = String(answers(frames).find(frame => frame.type === 'conversation_list')?.conversations?.[2]?.sessionId);

    const client = new WebSocket(`${base}?sessionId=${picked}`, [HAL_WS_SUBPROTOCOL, 't']);
    clients.push(client);
    const rejoined: Frame[] = [];
    await new Promise<void>(resolve => {
      client.on('message', raw => {
        const frame = JSON.parse(String(raw)) as Frame;
        rejoined.push(frame);
        if (frame.type === 'connected') client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        if (frame.type === 'pong') resolve();
      });
    });

    expect({
      picked,
      connected: {sessionId: rejoined[0].sessionId, resumed: rejoined[0].resumed},
      replayed: rejoined.filter(frame => frame.type === 'entry_upsert').map(frame => frame.entry?.content),
    }).toEqual({
      picked: 'c-old',
      connected: {sessionId: 'c-old', resumed: true},
      replayed: ['said in c-old'],
    });
  });
});

